#!/usr/bin/env python3
"""gen-shell-data.py — write the shell's generated files from the design system (LLD D4).

Usage:
  python3 scripts/gen-shell-data.py           # write every output
  python3 scripts/gen-shell-data.py --check   # write nothing; exit 1 when an output is stale

Outputs (committed; never hand-edit):
  shell/MatShell/Tokens/*                      byte-for-byte copy of design-system/tokens/qml/*
  shell/lib/generated/widgetOptionsSchema.mjs  WIDGET_OPTIONS, WIDGET_OPTION_MIGRATIONS (02-contracts.md §2.2)
  shell/lib/generated/barPresets.mjs           BAR_PRESETS, BAR_GUARDRAILS, WIDGET_TYPES
  shell/assets/matugen/{config.toml,theme.json.tpl}  byte-for-byte copy; ThemeService seeds the user's matugen folder from it
"""
import json
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
TOKENS_SRC = ROOT / "design-system" / "tokens" / "qml"
TOKENS_OUT = ROOT / "shell" / "MatShell" / "Tokens"
GENERATED = ROOT / "shell" / "lib" / "generated"
MATUGEN_SRC = ROOT / "design-system" / "tokens" / "matugen"
MATUGEN_OUT = ROOT / "shell" / "assets" / "matugen"
MATUGEN_FILES = ("config.toml", "theme.json.tpl")  # theme.baseline.json is not needed at runtime: ColorTokens defaults mirror it
HEADER = "// GENERATED by scripts/gen-shell-data.py from design-system/tokens/m3-tokens.json. Do not edit.\n"


def module(exports):
    body = "".join(f"export const {name} = {json.dumps(value, indent=2, ensure_ascii=False)};\n" for name, value in exports)
    return (HEADER + body).encode("utf-8")


def outputs():
    """{path: bytes} for every generated file."""
    bars = json.loads((ROOT / "design-system" / "tokens" / "m3-tokens.json").read_text(encoding="utf-8"))["modes"]["bars"]
    files = {TOKENS_OUT / p.name: p.read_bytes() for p in sorted(TOKENS_SRC.iterdir()) if p.is_file() and p.name != ".DS_Store"}
    files.update({MATUGEN_OUT / name: (MATUGEN_SRC / name).read_bytes() for name in MATUGEN_FILES})
    files[GENERATED / "widgetOptionsSchema.mjs"] = module([
        ("WIDGET_OPTIONS", {k: v for k, v in bars["widgetOptions"].items() if k != "$spec"}),
        ("WIDGET_OPTION_MIGRATIONS", bars["widgetOptionMigrations"]),
    ])
    files[GENERATED / "barPresets.mjs"] = module([
        ("BAR_PRESETS", bars["presets"]),
        ("BAR_GUARDRAILS", bars["guardrails"]),
        ("WIDGET_TYPES", bars["widgetTypes"]),
    ])
    return files


def main(argv):
    files = outputs()
    if "--check" in argv:
        stale = [p for p, data in files.items() if not p.exists() or p.read_bytes() != data]
        stale += [p for d in (TOKENS_OUT, MATUGEN_OUT) for p in d.glob("*") if p.is_file() and p.name != ".DS_Store" and p not in files]
        if stale:
            for p in stale:
                print(f"ERROR: stale {p.relative_to(ROOT)} (run python3 scripts/gen-shell-data.py)")
            sys.exit(1)
        print("  ✓ generated shell data is up to date")
        return
    for p, data in files.items():
        p.parent.mkdir(parents=True, exist_ok=True)
        p.write_bytes(data)
    print(f"wrote {len(files)} generated files")


if __name__ == "__main__":
    main(sys.argv)
